WITH bounds AS (SELECT timestamptz '2026-09-01 06:00:00+00' AS lo,timestamptz '2026-10-01 06:00:00+00' AS hi),
patterns(pat) AS (VALUES ('josephsskaf@gmail.com'),('josephskaf@hotmail.com'),('victoriaskaf96@gmail.com'),('joseph+teste01@gmail.com'),('teste01@shortsforgeai.com'),('josephsskaf+%@gmail.com'),('joseph+%@gmail.com'),('joseph+%'),('victoriaskaf%'),('%@theresanaiforthat.com'),('josephsskaf%'),('josephskaf%'),('%@shortsforgeai.com'),('test%'),('%mailinator%'),('smoketest%')),
people AS (SELECT p.id,p.created_at,coalesce(nullif(trim(p.signup_utm_source),''),nullif(trim(p.utm_source),''),'unknown') source,p.signup_utm_campaign campaign FROM profiles p WHERE NOT EXISTS (SELECT 1 FROM patterns i WHERE lower(trim(coalesce(p.email,''))) LIKE i.pat)),
payments AS (SELECT e.user_id,e.created_at,e.metadata FROM events e JOIN people p ON p.id=e.user_id CROSS JOIN bounds b WHERE e.name='payment_success' AND e.created_at>=b.lo AND e.created_at<b.hi)
SELECT jsonb_build_object('payment_groups',(SELECT jsonb_agg(x) FROM (SELECT metadata->>'checkout_mode' mode,metadata->>'kind' kind,metadata->>'card_trial' card_trial,metadata->>'tier' tier,count(*) events,count(DISTINCT user_id) people FROM payments GROUP BY 1,2,3,4)x),'first_positive_subscription_people',(SELECT count(DISTINCT x.user_id) FROM payments x WHERE x.metadata->>'checkout_mode'='subscription' AND (x.metadata->>'amount_total')::numeric>0 AND NOT EXISTS(SELECT 1 FROM events old WHERE old.user_id=x.user_id AND old.name='payment_success' AND old.created_at<x.created_at AND old.metadata->>'checkout_mode'='subscription' AND (old.metadata->>'amount_total')::numeric>0)),'payments_before_first_video_people',(SELECT count(DISTINCT x.user_id) FROM payments x WHERE NOT EXISTS(SELECT 1 FROM videos v WHERE v.user_id=x.user_id AND v.status='completed' AND coalesce(nullif(v.final_video_url,''),nullif(v.video_url,'')) IS NOT NULL AND v.created_at<x.created_at)),'missing_email_cohort',(SELECT count(*) FROM profiles p,bounds b WHERE p.created_at>=b.lo AND p.created_at<b.hi AND nullif(trim(p.email),'') IS NULL)) measurement;
